package solution

import (
	"math"
	"reflect"
	"testing"
)

func TestBestGateSelectsNearestUsableGate(t *testing.T) {
	gates := []Gate{
		{Distance: 20, Grace: 10},
		{Distance: 4, Grace: 1},
		{Distance: 10, Grace: 5},
	}
	original := append([]Gate(nil), gates...)

	travelTime, ok, err := BestGate(gates, 1, 2)
	if err != nil {
		t.Fatalf("BestGate returned error: %v", err)
	}
	if !ok || travelTime != 10 {
		t.Fatalf("BestGate returned (%v, %v), want (10, true)", travelTime, ok)
	}
	if !reflect.DeepEqual(gates, original) {
		t.Fatal("BestGate mutated its gate slice")
	}
}

func TestBestGateGraceBoundaryAndZeroDistance(t *testing.T) {
	travelTime, ok, err := BestGate([]Gate{{Distance: 2, Grace: 1}}, 1, 2)
	if err != nil || !ok || travelTime != 2 {
		t.Fatalf("boundary gate returned (%v, %v, %v), want (2, true, nil)", travelTime, ok, err)
	}

	travelTime, ok, err = BestGate([]Gate{{Distance: 0, Grace: 0}}, 3, 3)
	if err != nil || !ok || travelTime != 0 {
		t.Fatalf("zero-distance gate returned (%v, %v, %v), want (0, true, nil)", travelTime, ok, err)
	}
}

func TestBestGateEmptyAndUnusableInputs(t *testing.T) {
	tests := [][]Gate{
		nil,
		{},
		{{Distance: 10, Grace: 4}},
	}
	for i, gates := range tests {
		travelTime, ok, err := BestGate(gates, 1, 2)
		if err != nil || ok || travelTime != 0 {
			t.Errorf("case %d returned (%v, %v, %v), want (0, false, nil)", i, travelTime, ok, err)
		}
	}
}

func TestBestGateRejectsInvalidSpeeds(t *testing.T) {
	invalid := [][2]float64{
		{0, 1},
		{-1, 1},
		{2, 1},
		{math.NaN(), 1},
		{1, math.NaN()},
		{math.Inf(1), math.Inf(1)},
		{1, math.Inf(1)},
		{math.Inf(-1), 1},
	}
	for i, speeds := range invalid {
		travelTime, ok, err := BestGate(nil, speeds[0], speeds[1])
		if err == nil || ok || travelTime != 0 {
			t.Errorf("case %d returned (%v, %v, %v), want zero, false, error", i, travelTime, ok, err)
		}
	}
}

func TestBestGateRejectsEveryMalformedGate(t *testing.T) {
	invalidGates := []Gate{
		{Distance: -1, Grace: 0},
		{Distance: 1, Grace: -1},
		{Distance: math.NaN(), Grace: 0},
		{Distance: 1, Grace: math.NaN()},
		{Distance: math.Inf(1), Grace: 0},
		{Distance: 1, Grace: math.Inf(-1)},
	}
	for i, gate := range invalidGates {
		gates := []Gate{{Distance: 0, Grace: 0}, gate}
		travelTime, ok, err := BestGate(gates, 1, 2)
		if err == nil || ok || travelTime != 0 {
			t.Errorf("case %d returned (%v, %v, %v), want zero, false, error", i, travelTime, ok, err)
		}
	}
}

